	,showSplash: function() {
		this.set_visible(true);
		this.inputRef.flushInputs();
		this.splashInputCooldown = 0.35;
		this.currentState = core_UIState.Splash;
		this.modalDimmer.set_visible(false);
		this.cardBg.set_visible(false);
		this.splashContainer.set_visible(true);
		this.mainMenuContainer.set_visible(false);
		this.pauseContainer.set_visible(false);
		this.optionsContainer.set_visible(false);
		this.creditsContainer.set_visible(false);
		this.helpText.set_visible(false);
		this.layout();
	}
	,showMainMenu: function() {
		this.inputRef.flushInputs();
		this.currentState = core_UIState.MainMenu;
		this.modalDimmer.set_visible(true);
		this.cardBg.set_visible(true);
		this.splashContainer.set_visible(false);
		this.mainMenuContainer.set_visible(true);
		this.pauseContainer.set_visible(false);
		this.optionsContainer.set_visible(false);
		this.creditsContainer.set_visible(false);
		this.helpText.set_text("[Up / Down / D-Pad] Select    [A / Enter] Confirm");
		this.helpText.set_visible(true);
		this.mainSelectedIndex = this.hasActiveSave ? 1 : 0;
		this.updateMainMenuStyles();
		this.layout();
	}
