	,updateControlViewMode: function() {
		this.diagramViewer.set_visible(this.controlViewMode == "Diagram");
		this.remapContainer.set_visible(this.controlViewMode == "Custom");
		if(this.controlViewMode == "Diagram") {
			if(this.currentTab == core_OptionsTab.Keyboard) {
				this.diagramViewer.drawKeyboardLayout();
			} else {
				this.diagramViewer.drawGamepadLayout();
			}
		} else {
			this.updateRemapStyles();
		}
		this.updateControlHeaderButtons();
		this.layout();
	}
	,updateControlHeaderButtons: function() {
		var isKbd = this.currentTab == core_OptionsTab.Keyboard;
		var active = this.inputRef.exclusiveDevice;
		var status = "BOTH ACTIVE";
		if(active == input_ExclusiveDevice.KeyboardOnly) {
			status = isKbd ? "EXCLUSIVE (ACTIVE)" : "MUTED";
		} else if(active == input_ExclusiveDevice.GamepadOnly) {
			status = !isKbd ? "EXCLUSIVE (ACTIVE)" : "MUTED";
		}
		this.toggleExclusiveBtn.set_text("[DEVICE: " + status + "]");
		this.toggleExclusiveBtn.set_textColor(status.indexOf("MUTED") >= 0 ? 14707829 : 10011513);
		this.toggleViewModeBtn.set_text("[MODE: " + (this.controlViewMode == "Diagram" ? "DEFAULT DIAGRAM" : "CUSTOM REMAPPING") + "]");
		this.toggleViewModeBtn.set_textColor(58879);
	}
	,toggleExclusiveDevice: function() {
		core_AudioManager.inst.playMenuBeep(480,0.06);
		if(this.currentTab == core_OptionsTab.Keyboard) {
			this.inputRef.exclusiveDevice = this.inputRef.exclusiveDevice == input_ExclusiveDevice.KeyboardOnly ? input_ExclusiveDevice.Both : input_ExclusiveDevice.KeyboardOnly;
		} else if(this.currentTab == core_OptionsTab.Gamepad) {
			this.inputRef.exclusiveDevice = this.inputRef.exclusiveDevice == input_ExclusiveDevice.GamepadOnly ? input_ExclusiveDevice.Both : input_ExclusiveDevice.GamepadOnly;
		}
		this.updateControlHeaderButtons();
	}
	,triggerRemapEntry: function(idx) {
		if(idx == 6) {
			core_AudioManager.inst.playMenuBeep(320,0.08);
			if(this.currentTab == core_OptionsTab.Keyboard) {
				this.inputRef.bindings.resetKeyboardDefaults();
			} else {
				this.inputRef.bindings.resetGamepadDefaults();
			}
			this.updateRemapStyles();
			return;
		}
		var isGamepad = this.currentTab == core_OptionsTab.Gamepad;
		core_AudioManager.inst.playMenuBeep(640,0.1);
		this.remapStatusNotice.set_text("PRESS ANY " + (isGamepad ? "BUTTON" : "KEY") + "...");
		this.remapStatusNotice.set_visible(true);
		this.inputRef.startListening([input_InputAction.Throttle,input_InputAction.Brake,input_InputAction.SteerLeft,input_InputAction.SteerRight,input_InputAction.Handbrake,input_InputAction.Boost][idx],isGamepad);
	}
