	,adjustVolume: function(channel,delta) {
		var am = core_AudioManager.inst;
		switch(channel) {
		case 0:
			am.masterVolume = Math.max(0.0,Math.min(1.0,am.masterVolume + delta));
			break;
		case 1:
			am.musicVolume = Math.max(0.0,Math.min(1.0,am.musicVolume + delta));
			break;
		case 2:
			am.sfxVolume = Math.max(0.0,Math.min(1.0,am.sfxVolume + delta));
			break;
		}
		am.playMenuBeep(480 + channel * 60,0.05);
		this.updateAudioStyles();
	}
	,drawBackplates: function() {
		this.cardBg.clear();
		if(!this.cardBg.visible) {
			return;
		}
		var sw = hxd_Window.getInstance().get_width();
		var sh = hxd_Window.getInstance().get_height();
		this.cardBg.beginFill(1251103,0.88);
		this.cardBg.lineStyle(2.0,58879,0.45);
		if(this.currentState == core_UIState.MainMenu) {
			var cardX = (sw - 540) * 0.5;
			this.cardBg.drawRoundedRect(cardX,sh * 0.28,540,360,14);
			var activeY = sh * 0.32 + this.mainSelectedIndex * 52;
			this.cardBg.beginFill(58879,0.12);
			this.cardBg.lineStyle(1.5,58879,0.7);
			this.cardBg.drawRoundedRect(cardX + 24,activeY - 4,492,44,8);
		} else if(this.currentState == core_UIState.PauseMenu) {
			var cardX = (sw - 500) * 0.5;
			this.cardBg.drawRoundedRect(cardX,sh * 0.32,500,320,14);
			var activeY = sh * 0.38 + this.pauseSelectedIndex * 54;
			this.cardBg.beginFill(58879,0.12);
			this.cardBg.lineStyle(1.5,58879,0.7);
			this.cardBg.drawRoundedRect(cardX + 24,activeY - 4,452,44,8);
		} else if(this.currentState == core_UIState.OptionsMenu) {
			this.cardBg.drawRoundedRect((sw - 920) * 0.5,sh * 0.16,920,560,16);
			var tabX = (sw - core_UIManager.TAB_ORDER.length * 170) * 0.5 + core_UIManager.TAB_ORDER.indexOf(this.currentTab) * 170;
			this.cardBg.beginFill(58879,0.18);
			this.cardBg.lineStyle(2.0,58879,0.9);
			this.cardBg.drawRoundedRect(tabX + 6,sh * 0.18 - 4,150,42,8);
		} else if(this.currentState == core_UIState.CreditsScreen) {
			var cardX = (sw - 860) * 0.5;
			this.cardBg.drawRoundedRect(cardX,sh * 0.12,860,610,16);
			this.cardBg.beginFill(58879,0.08);
			this.cardBg.lineStyle(1.5,58879,0.4);
			this.cardBg.drawRoundedRect(cardX + 32,sh * 0.22,796,76,10);
		}
		this.cardBg.endFill();
	}
